    max_heap = [-count for count in task_counts.values()]
    heapq.heapify(max_heap)

    total_time = 0
    while max_heap:
        # List to hold the next batch of tasks to be executed
        next_batch = []
        for _ in range(n + 1):
            if max_heap:
                # Execute the most frequent task
                count = -heapq.heappop(max_heap)
                if count > 1:
                    next_batch.append(count - 1)
            else:
                # If no tasks left, break the loop
                break

        # Push the remaining tasks back into the heap
        for count in next_batch:
            heapq.heappush(max_heap, -count)

        # Increment total time by (n + 1) or the number of tasks executed
        total_time += (n + 1) if max_heap else len(next_batch)

    return total_time

