class HitCounter:
    def __init__(self):
        # Initialize an empty list to store the timestamps of hits
        self.hits = []

    def hit(self, timestamp: int) -> None:
        # Record a hit by appending the timestamp to the hits list
        self.hits.append(timestamp)

    def get_hits(self, timestamp: int) -> int:
        # Remove all timestamps that are older than 300 seconds from the current timestamp
        while self.hits and timestamp - self.hits[0] >= 300:
            self.hits.pop(0)
        # Return the number of hits in the past 300 seconds
        return len(self.hits)

